        // one legacy look value of a race, sex and class set: the option and choice ids of 9.x and later; rows with a
        // dependency apply only when the dependent legacy value matches
        struct ConversionRow
        {
            uint64_t raceMask;
            uint16_t classMask;
            uint8_t sex;
            uint8_t legacyOption;
            uint8_t legacyValue;
            uint8_t dependentOption;
            uint8_t dependentValue;
            uint16_t optionId;
            uint16_t choiceId;
        };

